SELECT id, store_id, product_id, sale_date, NTILE(4) OVER w_hist AS revenue_bucket, COUNT(revenue) OVER (PARTITION BY store_id) AS store_id_count_revenue, DENSE_RANK() OVER (PARTITION BY MONTH(sale_date) ORDER BY revenue DESC NULLS LAST) AS revenue_dense_rank, ROW_NUMBER() OVER w_recent AS row_seq, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date, id) AS event_seq FROM store_sales WHERE revenue <= 1900 WINDOW w_hist AS (PARTITION BY product_id, store_id ORDER BY revenue, id), w_recent AS (PARTITION BY store_id ORDER BY revenue, id)
